mod core;mod packet;mod sparse;mod action;mod geometry;mod index;mod verifier;mod reference;mod qualify;mod build_packet;
#[path="../source-phases/phase.rs"]mod phase;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng,instance::factor_base};
fn run(c:&Curve,pt:(u64,u64),d:&Div,t:&Div,ell:u64,sm:u64,gate:bool)->Vec<core::Trace>{let mut out=vec![];for seed in 1..=3{let trace=core::solve(c,pt,d,t,ell,sm,seed,gate,true);let done=trace.answer.is_some();out.push(trace);if done{break}}out}
fn main(){counted::disable();geometry::controls();geometry::repeated_control();action::controls();let old:Vec<Vec<&str>>=include_str!("../root-pipeline/CONTROL.tsv").lines().skip(1).map(|l|l.split('\t').collect()).collect();let(mut certs,mut repetitions,mut intersections,mut fallbacks,mut attempts)=(0,0,0,0,0);
 for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);for sm in [1,17]{let d=c.mul(&base,sm);for case in 0..2{let expected=1+rng.below(ell-1);let t=c.mul(&d,expected);let diagnostic=run(&c,pt,&d,&t,ell,sm,true);counted::reset();let traces=run(&c,pt,&d,&t,ell,sm,false);let counts=counted::snapshot();counted::disable();assert_eq!(traces,diagnostic);for(m,v)in &counts{let row=old.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]=="0"&&x[4]=="1"&&x[5]==m.to_string()).unwrap();let expected:Vec<u64>=row[12].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(v.as_slice(),expected.as_slice());}let last=traces.last().unwrap();assert_eq!(last.answer.map(|x|x.1),Some(expected));let cert=build_packet::build(&c,&d,&t,ell,sm,last);phase::reset();qualify::qualify(&cert);assert_eq!(cert.k,expected);certs+=1;attempts+=traces.len();
 let mut anchors=vec![t];for _ in 0..16{let a=c.add(anchors.last().unwrap(),&d);anchors.push(a);}for prim in &last.primitives{let xs:std::collections::BTreeSet<_>=prim.points.iter().map(|p|p.0).collect();if xs.len()<3{repetitions+=1;}if prim.points.iter().any(|p|anchors[prim.a as usize].u.eval(p.0,&c.fp)==0){intersections+=1;}if !geometry::roots(&c,&anchors[prim.a as usize],prim.t,&prim.points){fallbacks+=1;}}
 println!("PASS\tp={p}\tsm={sm}\tcase={case}\tattempts={}\tpoints={}\tprimitive_rows={}\tk={expected}",traces.len(),last.points.len(),last.primitives.len());println!("CERT\tp={p}\tsm={sm}\tcase={case}\tpacket={cert:?}");println!("TRACE\tp={p}\tsm={sm}\tcase={case}\tattempts={traces:?}");}}}
 assert_eq!(certs,12);eprintln!("original_certificates={certs} mutations_rejected_each_verifier=84 original_producer_vectors_exact=true diagnostic_trace_native_relations_exact=true total_attempts={attempts} repeated_residual_rows={repetitions} anchor_intersection_rows={intersections} exact_fallback_rows={fallbacks} no_certificate_cost_claim=true independent_verification=false");}
